// Match data is never presented from the service-worker offline cache. Also
// invalidate the page's short-lived memory cache and in-flight render tokens.
function footballDisconnected(){
 sportsEpoch++;sportsCache.clear();sportsPending.clear();scoreRequest++;fixtureRequest++;apiRequestVersion++;matchCentre.invalidate('Di luar talian. Data perlawanan memerlukan internet.');
 apiCheck.disabled=true;
 for(const id of ['scoreContent','fixturesContent','playerResults']){
  const box=$(id);box.replaceChildren(safeText('p','Di luar talian. Data perlawanan dan carian pemain memerlukan internet.'));
  box.setAttribute('aria-busy','false');box.classList.add('offline-data');
 }
 apiResults.replaceChildren(safeText('p','Di luar talian. Tiada skor tersimpan dipaparkan.'));
}
window.addEventListener('offline',footballDisconnected);
window.addEventListener('online',()=>{
 sportsEpoch++;sportsPending.clear();sportsCache.clear();apiCheck.disabled=Date.now()<apiBlockedUntil;
 const scoreLeague=document.querySelector('[data-score][aria-pressed="true"]')?.dataset.score||'4328';
 const fixtureLeague=document.querySelector('[data-fixture][aria-pressed="true"]')?.dataset.fixture||'epl';
 showError($('scoreContent'),'Sambungan pulih. Semak semula untuk mendapatkan data baharu.',()=>loadScores(scoreLeague));
 showError($('fixturesContent'),'Sambungan pulih. Semak semula jadual daripada pembekal.',()=>showFixtures(fixtureLeague));
 $('playerResults').replaceChildren(safeText('p','Sambungan pulih. Jalankan carian pemain semula.'));
 apiResults.replaceChildren();
});
if(!navigator.onLine)footballDisconnected();
// iOS can suspend tabs without delivering an offline event. Recheck on return
// and remove expired score/fixture panels rather than implying they are live.
function checkFootballFreshness(){
 if(!navigator.onLine){footballDisconnected();return}
 const scoreLeague=document.querySelector('[data-score][aria-pressed="true"]')?.dataset.score||'4328';
 const scoreAt=Math.min(sportsCache.get('eventsnextleague.php?id='+scoreLeague)?.at||Infinity,sportsCache.get('eventspastleague.php?id='+scoreLeague)?.at||Infinity);
 if(Date.now()-scoreAt>=sportsTTL){scoreRequest++;matchCentre.invalidate('Paparan perlawanan ini telah luput. Semak semula untuk data baharu.')}
 const fixtureLeague=document.querySelector('[data-fixture][aria-pressed="true"]')?.dataset.fixture||'epl';
 const fixtureId=fixtureInfo[fixtureLeague]?.id;
 const fixtureAt=fixtureId?sportsCache.get('eventsnextleague.php?id='+fixtureId)?.at:undefined;
 if(fixtureAt&&Date.now()-fixtureAt>=sportsTTL){fixtureRequest++;showError($('fixturesContent'),'Paparan jadual ini telah luput. Semak semula untuk data baharu.',()=>showFixtures(fixtureLeague))}
}
window.addEventListener('pageshow',checkFootballFreshness);
document.addEventListener('visibilitychange',()=>{if(!document.hidden)checkFootballFreshness()});
